    def from_api(cls, data: Dict[str, Any]) -> "DiarizedTranscript":
        segments = [TranscriptionSegment.from_api(s) for s in data.get("segments", []) or []]
        return cls(segments=segments, text=data.get("text") or data.get("transcript") or "")


